// Originally generated by CLI Printing Press. Hand-edited in Phase 3 to add
// local multi-axis filter flags (--batch, --industry, --tag, --hiring, ...)
// against the synced companies table. The live API only serves whole-corpus
// JSON; the filter behaviour the absorb manifest promises is local.

package cli

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/spf13/cobra"

	"github.com/mvanhorn/printing-press-library/library/sales-and-crm/yc-companies/internal/store"
)

func newCompaniesListCmd(flags *rootFlags) *cobra.Command {
	var (
		batchF        string
		industryF     string
		tagF          string
		statusF       string
		regionF       string
		highlightF    string
		hiringF       bool
		topF          bool
		nonprofitF    bool
		minTeamSize   int
		maxTeamSize   int
		launchedAfter string
		limitF        int
	)

	cmd := &cobra.Command{
		Use:   "list",
		Short: "List YC companies, filtered locally by batch, industry, tag, status, region, team size, or hiring/top/nonprofit flags.",
		Long: "Reads from the local SQLite store synced via 'yc-companies-pp-cli sync'. " +
			"Apply any combination of filters; the query composes them with AND semantics. " +
			"When no filter flags are set, returns the full corpus (5,889+ companies). " +
			"Use --data-source live to bypass local and fetch /companies/all.json directly (no filtering).",
		Example: strings.Trim(`
  # All companies in the W25 batch
  yc-companies-pp-cli companies list --batch w25 --json

  # Fintech companies hiring in the US
  yc-companies-pp-cli companies list --industry Fintech --hiring --region "United States" --json

  # AI tag, batches Spring 2024 onward
  yc-companies-pp-cli companies list --tag "Artificial Intelligence" --launched-after 2024-01-01 --limit 50

  # Acquired companies with at least 100 employees
  yc-companies-pp-cli companies list --status acquired --min-team-size 100 --json
`, "\n"),
		Annotations: map[string]string{
			"pp:endpoint":   "companies.list",
			"pp:method":     "GET",
			"pp:path":       "/companies/all.json",
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			anyFilter := batchF != "" || industryF != "" || tagF != "" || statusF != "" ||
				regionF != "" || highlightF != "" || hiringF || topF || nonprofitF ||
				minTeamSize > 0 || maxTeamSize > 0 || launchedAfter != "" || limitF > 0

			useLive := flags.dataSource == "live" || (flags.dataSource == "auto" && !anyFilter)

			if dryRunOK(flags) {
				return nil
			}

			if !useLive {
				return runLocalList(cmd, flags, localListFilters{
					Batch:         batchF,
					Industry:      industryF,
					Tag:           tagF,
					Status:        statusF,
					Region:        regionF,
					Highlight:     highlightF,
					Hiring:        hiringF,
					Top:           topF,
					Nonprofit:     nonprofitF,
					MinTeamSize:   minTeamSize,
					MaxTeamSize:   maxTeamSize,
					LaunchedAfter: launchedAfter,
					Limit:         limitF,
				})
			}

			// Live path — fetch the whole index from yc-oss/api.
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			path := "/companies/all.json"
			params := map[string]string{}
			data, prov, err := resolveRead(cmd.Context(), c, flags, "companies", false, path, params, nil)
			if err != nil {
				return classifyAPIError(err, flags)
			}
			{
				var countItems []json.RawMessage
				_ = json.Unmarshal(data, &countItems)
				printProvenance(cmd, len(countItems), prov)
			}
			if flags.asJSON || (!isTerminal(cmd.OutOrStdout()) && !flags.csv && !flags.quiet && !flags.plain) {
				filtered := data
				if flags.selectFields != "" {
					filtered = filterFields(filtered, flags.selectFields)
				} else if flags.compact {
					filtered = compactFields(filtered)
				}
				wrapped, wrapErr := wrapWithProvenance(filtered, prov)
				if wrapErr != nil {
					return wrapErr
				}
				return printOutput(cmd.OutOrStdout(), wrapped, true)
			}
			if wantsHumanTable(cmd.OutOrStdout(), flags) {
				var items []map[string]any
				if json.Unmarshal(data, &items) == nil && len(items) > 0 {
					if err := printAutoTable(cmd.OutOrStdout(), items); err != nil {
						return err
					}
					if len(items) >= 25 {
						fmt.Fprintf(os.Stderr, "\nShowing %d results. To narrow: add --limit, --json --select, or filter flags.\n", len(items))
					}
					return nil
				}
			}
			return printOutputWithFlags(cmd.OutOrStdout(), data, flags)
		},
	}

	cmd.Flags().StringVar(&batchF, "batch", "", "Filter to a YC batch (e.g. 'Winter 2025', 'w25', 'winter-2025').")
	cmd.Flags().StringVar(&industryF, "industry", "", "Filter to an industry vertical (e.g. Fintech, Healthcare, B2B).")
	cmd.Flags().StringVar(&tagF, "tag", "", "Filter to companies tagged with this label (substring; case-insensitive).")
	cmd.Flags().StringVar(&statusF, "status", "", "Filter by company status: Active | Acquired | Public | Inactive.")
	cmd.Flags().StringVar(&regionF, "region", "", "Filter to companies operating in this region (substring; case-insensitive).")
	cmd.Flags().StringVar(&highlightF, "highlight", "", "Filter to founder demographic highlights: women | black | latinx.")
	cmd.Flags().BoolVar(&hiringF, "hiring", false, "Only companies currently hiring.")
	cmd.Flags().BoolVar(&topF, "top", false, "Only top-ranked YC companies.")
	cmd.Flags().BoolVar(&nonprofitF, "nonprofit", false, "Only nonprofit YC companies.")
	cmd.Flags().IntVar(&minTeamSize, "min-team-size", 0, "Minimum team_size (inclusive).")
	cmd.Flags().IntVar(&maxTeamSize, "max-team-size", 0, "Maximum team_size (inclusive; 0 = no max).")
	cmd.Flags().StringVar(&launchedAfter, "launched-after", "", "Only companies launched after this date (YYYY-MM-DD).")
	cmd.Flags().IntVar(&limitF, "limit", 0, "Maximum rows to return (0 = unlimited).")

	return cmd
}

type localListFilters struct {
	Batch         string
	Industry      string
	Tag           string
	Status        string
	Region        string
	Highlight     string
	Hiring        bool
	Top           bool
	Nonprofit     bool
	MinTeamSize   int
	MaxTeamSize   int
	LaunchedAfter string
	Limit         int
}

func runLocalList(cmd *cobra.Command, flags *rootFlags, f localListFilters) error {
	st, err := store.OpenWithContext(cmd.Context(), defaultDBPath("yc-companies-pp-cli"))
	if err != nil {
		return err
	}
	defer st.Close()
	db := st.DB()

	var (
		where []string
		args  []any
	)
	if f.Batch != "" {
		// Accept Winter 2025 / winter-2025 / w25 — fall through to LIKE on canonical batch.
		batchCandidates := normalizeBatch(f.Batch)
		placeholders := make([]string, len(batchCandidates))
		for i, b := range batchCandidates {
			placeholders[i] = "LOWER(batch) = LOWER(?)"
			args = append(args, b)
		}
		where = append(where, "("+strings.Join(placeholders, " OR ")+")")
	}
	if f.Industry != "" {
		where = append(where, "(LOWER(industry) = LOWER(?) OR LOWER(industries) LIKE LOWER(?))")
		args = append(args, f.Industry, "%"+f.Industry+"%")
	}
	if f.Tag != "" {
		where = append(where, "LOWER(tags) LIKE LOWER(?)")
		args = append(args, "%"+f.Tag+"%")
	}
	if f.Status != "" {
		where = append(where, "LOWER(status) = LOWER(?)")
		args = append(args, f.Status)
	}
	if f.Region != "" {
		where = append(where, "LOWER(regions) LIKE LOWER(?)")
		args = append(args, "%"+f.Region+"%")
	}
	if f.Highlight != "" {
		col := highlightColumn(f.Highlight)
		if col == "" {
			return fmt.Errorf("--highlight: unknown value %q (use women, black, or latinx)", f.Highlight)
		}
		where = append(where, col+" = 1")
	}
	if f.Hiring {
		where = append(where, "is_hiring = 1")
	}
	if f.Top {
		where = append(where, "top_company = 1")
	}
	if f.Nonprofit {
		where = append(where, "nonprofit = 1")
	}
	if f.MinTeamSize > 0 {
		where = append(where, "team_size >= ?")
		args = append(args, f.MinTeamSize)
	}
	if f.MaxTeamSize > 0 {
		where = append(where, "team_size > 0 AND team_size <= ?")
		args = append(args, f.MaxTeamSize)
	}
	if f.LaunchedAfter != "" {
		t, err := time.Parse("2006-01-02", f.LaunchedAfter)
		if err != nil {
			if t2, e2 := time.Parse(time.RFC3339, f.LaunchedAfter); e2 == nil {
				t = t2
			} else {
				return fmt.Errorf("--launched-after: %w", err)
			}
		}
		where = append(where, "launched_at >= ?")
		args = append(args, t.Unix())
	}

	q := "SELECT data FROM companies"
	if len(where) > 0 {
		q += " WHERE " + strings.Join(where, " AND ")
	}
	q += " ORDER BY launched_at DESC, slug ASC"
	if f.Limit > 0 {
		q += " LIMIT ?"
		args = append(args, f.Limit)
	}

	rows, err := db.QueryContext(cmd.Context(), q, args...)
	if err != nil {
		return fmt.Errorf("local list: %w", err)
	}
	defer rows.Close()

	var out []json.RawMessage
	for rows.Next() {
		var raw []byte
		if err := rows.Scan(&raw); err != nil {
			return err
		}
		// Defensive: store may return non-JSON if synced as something else.
		var ok json.RawMessage = json.RawMessage(raw)
		out = append(out, ok)
	}
	if err := rows.Err(); err != nil {
		return err
	}

	dataBytes, _ := json.Marshal(out)
	prov := DataProvenance{Source: "local", ResourceType: "companies"}
	printProvenance(cmd, len(out), prov)

	if flags.asJSON || (!isTerminal(cmd.OutOrStdout()) && !flags.csv && !flags.quiet && !flags.plain) {
		filtered := dataBytes
		if flags.selectFields != "" {
			filtered = filterFields(filtered, flags.selectFields)
		} else if flags.compact {
			filtered = compactFields(filtered)
		}
		wrapped, wrapErr := wrapWithProvenance(filtered, prov)
		if wrapErr != nil {
			return wrapErr
		}
		return printOutput(cmd.OutOrStdout(), wrapped, true)
	}
	if wantsHumanTable(cmd.OutOrStdout(), flags) {
		var items []map[string]any
		if json.Unmarshal(dataBytes, &items) == nil && len(items) > 0 {
			if err := printAutoTable(cmd.OutOrStdout(), items); err != nil {
				return err
			}
			if len(items) >= 25 {
				fmt.Fprintf(os.Stderr, "\nShowing %d results. To narrow: add --limit, --json --select, or filter flags.\n", len(items))
			}
			return nil
		}
		if len(out) == 0 {
			fmt.Fprintln(cmd.OutOrStdout(), "(no companies match — try fewer filters, or 'sync' first)")
			return nil
		}
	}
	return printOutputWithFlags(cmd.OutOrStdout(), dataBytes, flags)
}

func highlightColumn(name string) string {
	switch strings.ToLower(name) {
	case "women", "women-founded", "w":
		return "json_extract(data, '$.highlight_women')"
	case "black", "black-founded", "b":
		return "json_extract(data, '$.highlight_black')"
	case "latinx", "hispanic-latino-founded", "latino", "hispanic", "l":
		return "json_extract(data, '$.highlight_latinx')"
	}
	return ""
}

// normalizeBatch turns user-supplied batch shorthand into one or more canonical
// "Season Year" candidates the local store may hold.
func normalizeBatch(input string) []string {
	input = strings.TrimSpace(input)
	if input == "" {
		return nil
	}
	// Direct match
	out := []string{input}
	if dashed := strings.ReplaceAll(input, "-", " "); dashed != input {
		out = append(out, dashed)
	}
	short := strings.ToLower(input)
	seasonMap := map[byte]string{'w': "Winter", 's': "Summer", 'f': "Fall"}
	if len(short) >= 3 {
		if season, ok := seasonMap[short[0]]; ok && short[1] >= '0' && short[1] <= '9' {
			year := 0
			for _, c := range short[1:] {
				if c < '0' || c > '9' {
					break
				}
				year = year*10 + int(c-'0')
			}
			if year > 0 && year < 100 {
				year += 2000
			}
			if year > 0 {
				out = append(out, fmt.Sprintf("%s %d", season, year))
			}
		}
	}
	for _, name := range []string{"winter", "spring", "summer", "fall", "late"} {
		if strings.HasPrefix(short, name) && len(short) > len(name) {
			yr := strings.TrimLeft(short[len(name):], " -")
			year := 0
			for _, c := range yr {
				if c < '0' || c > '9' {
					break
				}
				year = year*10 + int(c-'0')
			}
			if year > 0 && year < 100 {
				year += 2000
			}
			if year > 0 {
				out = append(out, fmt.Sprintf("%s %d", strings.Title(name), year)) // nolint:staticcheck
			}
		}
	}
	return out
}
